declaration:
FUNCTION_BLOCK FB

VAR_INPUT
    processLength : USINT;
    sensor1 : BOOL;
    sensor2 : BOOL;
    sensor3 : BOOL;
    sensor4 : BOOL;
    sensor5 : BOOL;
    station1Start : BOOL;
    station2Complete : BOOL;
    station3Complete : BOOL;
    station4Complete : BOOL;
    processSequence : ARRAY[1..8] OF USINT;
END_VAR
VAR_OUTPUT
    conveyorLeft : BOOL;
    conveyorRight : BOOL;
END_VAR
VAR
    phase : INT;          
    idx : INT;            
    curStation : INT;     
    dstStation : INT;     
    lenNow : INT;
    dstOK : BOOL;
    arrived : BOOL;
    startEdge : BOOL;
    startPrev : BOOL;
    compEdge : BOOL;
    comp2Prev : BOOL;
    comp3Prev : BOOL;
    comp4Prev : BOOL;
END_VAR

implementation:
startEdge := station1Start AND NOT startPrev;
startPrev := station1Start;
lenNow := processLength;


compEdge := FALSE;
IF phase = 2 THEN
    IF curStation = 2 THEN
        compEdge := station2Complete AND NOT comp2Prev;
    ELSIF curStation = 3 THEN
        compEdge := station3Complete AND NOT comp3Prev;
    ELSIF curStation = 4 THEN
        compEdge := station4Complete AND NOT comp4Prev;
    END_IF;
END_IF;
comp2Prev := station2Complete;
comp3Prev := station3Complete;
comp4Prev := station4Complete;

conveyorLeft := FALSE;
conveyorRight := FALSE;


IF phase = 0 THEN
    IF sensor1 AND startEdge THEN
        IF (lenNow >= 1) AND (lenNow <= 8) THEN
            dstStation := processSequence[1];
            dstOK := (dstStation >= 2) AND (dstStation <= 5);
            IF dstOK THEN
                idx := 1;
                curStation := 1;
                phase := 1;
            END_IF;
        END_IF;
    END_IF;
END_IF;


IF phase = 2 THEN
    IF compEdge THEN
        idx := idx + 1;
        IF (idx > lenNow) OR (idx > 8) THEN

            phase := 0;
        ELSE
            dstStation := processSequence[idx];
            dstOK := (dstStation >= 2) AND (dstStation <= 5);
            IF dstOK THEN
                phase := 1;
            ELSE
                phase := 0;
            END_IF;
        END_IF;
    END_IF;
END_IF;


IF phase = 1 THEN
    IF dstStation > curStation THEN
        conveyorRight := TRUE;
    ELSIF dstStation < curStation THEN
        conveyorLeft := TRUE;
    END_IF;
    arrived := FALSE;
    IF dstStation = 2 THEN
        arrived := sensor2;
    ELSIF dstStation = 3 THEN
        arrived := sensor3;
    ELSIF dstStation = 4 THEN
        arrived := sensor4;
    ELSIF dstStation = 5 THEN
        arrived := sensor5;
    END_IF;
    IF arrived THEN
        conveyorLeft := FALSE;
        conveyorRight := FALSE;
        curStation := dstStation;
        IF dstStation = 5 THEN

            phase := 0;
        ELSE

            phase := 2;
        END_IF;
    END_IF;
END_IF;
